import { COVER_WIDTH, COVER_HEIGHT } from "./blog-cover";

// Covers are generated by Pollinations.ai straight from a URL (no API key, no quota billing).
export function pollinationsPrompt(c: Record<string, string>) {
  const parts = [
    `Professional 16:9 immigration blog cover, beautiful recognizable landmarks of ${c.country}`,
    `topic: ${c.topic || c.title}`,
    `bold readable title text "${c.title}"`,
    "premium editorial design, natural lighting, navy and gold accents, empty top-right corner, no logo, no watermark",
    c.instructions ? `art direction: ${c.instructions}` : "",
  ];
  return parts.filter(Boolean).join(", ").slice(0, 900);
}

export function pollinationsUrl(prompt: string, seed = Math.floor(Math.random() * 1000000)) {
  return `https://image.pollinations.ai/prompt/${encodeURIComponent(prompt)}?width=${COVER_WIDTH}&height=${COVER_HEIGHT}&nologo=true&seed=${seed}`;
}

export async function generateCover(_token: string, context: Record<string, string>, _onPreview?: (url: string) => void) {
  const response = await fetch(pollinationsUrl(pollinationsPrompt(context)));
  if (!response.ok) throw new Error(`Image generation failed (${response.status}). Please try again.`);
  const blob = await response.blob();
  if (!blob.type.startsWith("image/")) throw new Error("No image was returned. Please try again.");
  return URL.createObjectURL(blob);
}

async function loadImage(url: string) {
  const blob = await (await fetch(url)).blob();
  return createImageBitmap(blob);
}

export async function brandCover(source: string, logoUrl: string) {
  const [image, logo] = await Promise.all([loadImage(source), loadImage(logoUrl)]);
  const canvas = document.createElement("canvas");
  canvas.width = COVER_WIDTH; canvas.height = COVER_HEIGHT;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("Your browser cannot prepare the cover image.");
  ctx.drawImage(image, 0, 0, COVER_WIDTH, COVER_HEIGHT);
  const scale = Math.min(320 / logo.width, 140 / logo.height);
  const width = logo.width * scale, height = logo.height * scale;
  const x = COVER_WIDTH - width - 80, y = 40;
  // The actual uploaded logo is composited pixel-for-pixel, never AI-recreated.
  ctx.fillStyle = "white";
  ctx.beginPath(); ctx.roundRect(x - 20, y, width + 40, height + 40, 12); ctx.fill();
  ctx.drawImage(logo, x, y + 20, width, height);
  image.close(); logo.close();
  return canvas.toDataURL("image/jpeg", 0.94);
}